#!/usr/bin/env node
// Marks the generated parser opaque to the type checker. tsconfig's "exclude" does not apply to files that hand-written
// code imports, and the generated code does not meet noUnusedLocals. Runs as part of `npm run generate`.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const generatedDir = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'generated');
const banner =
    '/* eslint-disable */\n// @ts-nocheck\n// Generated by ANTLR from backend/src/main/antlr. Do not edit.\n';

for (const file of readdirSync(generatedDir).filter((name) => name.endsWith('.ts'))) {
    const path = join(generatedDir, file);
    const source = readFileSync(path, 'utf8');
    if (source.startsWith(banner)) continue;
    writeFileSync(path, banner + source);
    console.log(`sealed ${file}`);
}
